"""Produce human-readable handoff and input provenance from completed outputs."""
import collections,csv,hashlib,io,json,logging,sys,zipfile
from pathlib import Path
import numpy as np
from rdkit import Chem,rdBase
from preprocess import ROOT,write_csv,dump

def readrows(p):
    with Path(p).open(encoding='utf-8',newline='') as f:return list(csv.DictReader(f))

def main():
    summary=json.loads((ROOT/'reports/pdbbind_summary.json').read_text())
    tables=json.loads((ROOT/'reports/table_summary.json').read_text())
    manifest=readrows(ROOT/'processed/pdbbind/manifest.csv')
    # Correct the initial run's warning wording: a failed fallback was not used.
    for r in manifest:
        if r['status']=='excluded':r['warnings']=';'.join(w for w in r['warnings'].split(';') if w!='SDF_INVALID_USED_MOL2')
    write_csv(ROOT/'processed/pdbbind/manifest.csv',manifest)
    write_csv(ROOT/'processed/pdbbind/excluded.csv',[r for r in manifest if r['status']!='accepted'])
    jp=ROOT/'processed/pdbbind/manifest.jsonl'
    records=[json.loads(line) for line in jp.read_text().splitlines()]
    byid={r['pdb_id']:r for r in manifest}
    for r in records:
        r['warnings']=byid[r['pdb_id']]['warnings']
        if byid[r['pdb_id']].get('split'):
            r['split']=byid[r['pdb_id']]['split'];r['protein_group']=byid[r['pdb_id']]['protein_group']
    jp.write_text(''.join(json.dumps(r)+'\n' for r in records),encoding='utf-8')
    summary['warnings']=dict(collections.Counter(w for r in manifest for w in r['warnings'].split(';') if w))
    dump(ROOT/'reports/pdbbind_summary.json',summary)
    # Separate assay-specific entry lists so users do not accidentally mix targets.
    for split in ('train','val','test'):
        rs=readrows(ROOT/f'processed/pdbbind/{split}.csv')
        for kind in ('Kd','Ki','IC50'):
            write_csv(ROOT/f'processed/pdbbind/by_affinity_type/{kind}/{split}.csv',[r for r in rs if r['affinity_type']==kind],list(rs[0]))
    stream=io.StringIO();handler=logging.StreamHandler(stream);logger=logging.getLogger('rdkit');logger.handlers=[handler];logger.propagate=False;rdBase.LogToPythonLogger()
    failures=[]
    with zipfile.ZipFile(ROOT/'P-L.zip') as z:
        for r in manifest:
            if r['status']!='excluded':continue
            detail=dict(pdb_id=r['pdb_id'],reason=r['exclusion_reasons'])
            for extension in ('sdf','mol2'):
                name=next(n for n in z.namelist() if n.endswith(f"/{r['pdb_id']}_ligand.{extension}"))
                stream.seek(0);stream.truncate(0);raw=z.read(name).decode()
                mol=Chem.MolFromMolBlock(raw.split('$$$$')[0],sanitize=True,removeHs=True) if extension=='sdf' else Chem.MolFromMol2Block(raw,sanitize=True,removeHs=True)
                detail[extension+'_parsed']=mol is not None;detail[extension+'_diagnostic']=stream.getvalue().strip()
            failures.append(detail)
    logger.removeHandler(handler);dump(ROOT/'reports/failed_ligand_diagnostics.json',failures)
    resultzip=Path(r'H:\siddu\results_to_copy.zip')
    with zipfile.ZipFile(resultzip) as z:
        assert z.testzip() is None
        results=dict(files=len(z.infolist()),checkpoint_count=sum(n.endswith('.pt') for n in z.namelist()),source_code_files=[n for n in z.namelist() if n.endswith(('.py','.ipynb'))],safe_inspection='Only text/JSON inspected; checkpoint pickle data was not loaded or executed.',runs={})
        for name in ('davis','kiba','metz'):
            args=json.loads(z.read(f'runs/{name}/args.json'))
            results['runs'][name]=dict(input_smiles_columns=args.get('smiles_columns'),target_columns=args.get('target_columns'),sequence_length=args.get('sequence_length'),test_scores=json.loads(z.read(f'runs/{name}/fold_0/test_scores.json')))
    dump(ROOT/'reports/results_archive_summary.json',results)
    provenance=[]
    for path in [ROOT/'davis.csv',ROOT/'kiba.csv',ROOT/'metz.csv',ROOT/'P-L.zip',ROOT/'P-L.tar.gz',resultzip,ROOT/'viewer/vendor/3Dmol-min.js']:
        h=hashlib.sha256()
        with path.open('rb') as f:
            for block in iter(lambda:f.read(8*1024*1024),b''):h.update(block)
        provenance.append(dict(path=str(path),bytes=path.stat().st_size,sha256=h.hexdigest()))
    dump(ROOT/'reports/input_provenance.json',provenance)
    explanations={
      'INDEX_FLAGS_INCOMPLETE_STRUCTURE':'The index says part of the structure is missing. Like a puzzle with missing pieces, it should not be used as a complete training example.',
      'INDEX_FLAGS_COVALENT_COMPLEX':'The compound makes a chemical bond to the protein. It needs special handling, so it is outside this ordinary noncovalent training set.',
      'CENSORED_OR_UNPARSEABLE_AFFINITY':'The score is a limit, such as less than 10, rather than one exact answer. It was kept for viewing but not treated as an exact training answer.',
      'SEVERE_PROTEIN_LIGAND_CLASH':'Some protein and compound atoms are less than 1 angstrom apart. They appear to overlap, so this example needs checking.',
      'DISCONNECTED_LIGAND':'The ligand file contains separate pieces that are not joined by chemical bonds. A reviewer must decide which pieces belong to the compound.',
      'LIGAND_CHEMISTRY_INVALID_IN_SDF_AND_MOL2':'RDKit cannot accept the chemical structure in either ligand file. The saved atom and bond description needs correction.'}
    simple=['# Errors and warnings explained simply','', 'The input files were not changed. An exclusion means this pipeline did not use that example for training; it does not prove the original experiment is wrong.','', '| Problem | Complexes | Simple explanation |','|---|---:|---|']
    for k,n in summary['exclusions'].items():simple.append(f'| {k} | {n:,} | {explanations.get(k,k)} |')
    simple+=['','A complex may have more than one problem, so these counts must not be added together.','', '**Two failed complex IDs: 3vjs and 3vjt.** Their ligand chemistry fails in both SDF and MOL2. Exact RDKit messages are saved in `failed_ligand_diagnostics.json`. They have no output graph.','', 'Other warnings:','', '- 1lvk: the SDF reader failed, but the MOL2 file worked. Its graph was recovered using MOL2.', '- 101 complexes: the ligand partial-charge calculation was unavailable. The values are marked unknown using a mask; they are not claimed to be neutral. See the manifest for IDs.', '- 8,231 complexes: separate ions or cofactors were omitted from the protein pocket graph. Those groups can matter biologically. The original full protein files remain in the archive.', '- All protein partial charges and protein chemical bond orders are unassigned. Distance connections are saved instead. This is not a simulation-ready force-field topology.','', '| CSV dataset | Duplicate rows removed | Rows with conflicting scores set aside |','|---|---:|---:|']
    for name in ('davis','kiba','metz'):
        counts=collections.Counter(r['reason'] for r in readrows(ROOT/f'processed/{name}/excluded_rows.csv'))
        simple.append(f"| {name.title()} | {counts['EXACT_DUPLICATE_REMOVED']:,} | {counts['SAME_PAIR_HAS_DIFFERENT_LABELS']:,} |")
    simple+=['','A duplicate is the same compound, same protein and same score written more than once. A conflict is the same compound and protein with different scores. Different experiments may produce different values; because this CSV has no experiment IDs, conditions or units, conflicting rows were set aside rather than averaged. Every removed row has its original CSV line number in `processed/<dataset>/excluded_rows.csv`.','', '**Model code recovered:** the archive lacked source code, but the original code was found in `H:/siddu/perceiver_gpu/model_2d` and copied to `model_source/`. All three score models now run. They read 2D compound features and protein sequences; the XYZ graph files belong to a separate 3D workflow.','', '**Missing 3D information in Davis, KIBA and Metz:** their CSVs contain SMILES, protein sequences and numbers. A sequence is a list of building blocks; it does not tell us the measured position of every atom or where the compound sits. No binding poses were invented for these rows.','', '**Motion:** the viewer moves the compound along an artificial path to explain the bound pose. It is not a real movie of binding. A physical simulation requires additional preparation and computation.']
    simple+=['', 'Exact chemistry error for both failed complexes: `Explicit valence for atom # 0 B, 5, is greater than permitted`. In simple words: the file gives a boron atom a bond arrangement this chemistry checker does not accept. This might need a corrected representation or specialist handling of boron chemistry; the automated result alone does not prove the experiment is wrong.']
    (ROOT/'reports/ERRORS_SIMPLE.md').write_text('\n'.join(simple)+'\n',encoding='utf-8')
    doc=['# Dataset preprocessing and 3D viewer','', 'Completed on 15 November 2026 using local files in `H:\\gfihm`.','', '## Results','', '| Dataset | Input examples | Accepted for prepared training pool | Other examples | Train | Validation | Test |','|---|---:|---:|---|---:|---:|---:|']
    c=summary['splits']['counts']
    doc.append(f"| PDBbind | 19,037 | 17,479 | 1,556 view only; 2 failed | {c['train']:,} | {c['val']:,} | {c['test']:,} |")
    for name,s in tables['datasets'].items():
        c=s['splits'];doc.append(f"| {name.title()} | {s['input_rows']:,} | {s['accepted_unique_pairs']:,} | {s['excluded_rows']:,} removed or set aside | {c['train']:,} | {c['val']:,} | {c['test']:,} |")
    doc+=['','Accepted means passed the documented preprocessing filters, not proven free of all biological or experimental problems. No model was trained or validated scientifically in this task.','', '## What was done','', '1. Matched all 19,037 structure IDs to the protein-ligand index. There are zero unmatched IDs. The tar archive contains the index; the ZIP contains structures. The package README describes the 2020R1 overlap set reprocessed with the v2024 workflow, with index updates in August 2025. It is not the entire v2024 dataset.', '2. Read all four structure files per ID (protein PDB, pocket PDB, ligand SDF and ligand MOL2), checking ZIP checksums. Validated finite protein coordinates and ligand chemistry with RDKit. Used the first protein model and highest-occupancy alternate atom location.', '3. Preserved the common experimental coordinate frame. Used heavy atoms, ligand chemical bonds, formal charges, estimated ligand partial charges, and masks for unavailable features. No new ligand conformation or docking pose was generated.', '4. Recomputed pockets as complete amino-acid residues with an atom within 6 angstroms of a ligand atom. Waters and separate cofactors/ions are omitted from pocket graphs. Original structures remain intact.', '5. Saved NPZ graphs with directed distance connections up to 4.5 angstroms, separate ligand chemical bonds, and geometric protein-ligand contacts up to 4 angstroms. A distance contact is not automatically a hydrogen bond.', '6. Made train/validation/test splits and checked overlap. CSV datasets are split by unique compound-protein pair; PDBbind groups complexes sharing any exact observed protein chain sequence.', '7. Saved every accepted/view-only graph, pocket PDB, ligand SDF, metadata and row-level manifests. Built and browser-tested a local 3D viewer.','', '## Affinity labels','', '`p_affinity = -log10(affinity in mol/L)`. For example, 10gs has Ki=0.4uM, so its pKi is approximately 6.398. Kd, Ki and IC50 retain their types and must not silently be treated as the same assay. Smaller concentration corresponds to a larger p-value. Inequality signs reverse after this conversion. The 270 non-exact labels are retained as bounds but excluded from ordinary exact-label regression.', '', 'The prepared pool contains 6,453 Kd, 4,475 Ki and 6,551 IC50 examples. Separate assay-specific split files are in `processed/pdbbind/by_affinity_type/<Kd|Ki|IC50>/`. Use these for a single-assay target or explicitly include assay type in a suitable model.', '', 'The three original CSV score scales are not declared in their headers. Their numeric values were preserved without re-logging or rescaling. KIBA scores must not be treated as molar concentration merely because they are numbers. Confirm Davis and Metz score definitions from the data source before scientific interpretation. No scores were pooled across the three datasets.', '', 'The archive also contains only 387 old processed CSV rows (309/39/39), without PDB IDs. These were audited and not used to label structures; the complete ID-based index was used instead.','', '## Overlap and limitations','', '- PDBbind: zero PDB-ID overlap and zero exact observed protein-chain sequence overlap across the three splits.', '- Identical ligand structures still overlap: 342 train/validation, 329 train/test, 112 validation/test. Similar protein sequences and similar chemical scaffolds were not clustered. These are not strict homology- or scaffold-disjoint benchmark splits.', '- CSV datasets: zero exact compound-protein pair overlap across their new splits, but individual compounds and proteins can appear on both sides. These are pair splits, not cold-target or cold-compound splits.', f"- Exact pair overlaps between datasets: Davis/KIBA {tables['cross_dataset_exact_pair_overlap']['davis-kiba']:,}; Davis/Metz {tables['cross_dataset_exact_pair_overlap']['davis-metz']:,}; KIBA/Metz {tables['cross_dataset_exact_pair_overlap']['kiba-metz']:,}. A shared pair is assigned to the same split across all three datasets. Do not count it as an independent external test example.", '- Cross-dataset overlap with PDBbind is not established: the CSVs lack PDB IDs and their sequences may differ from crystallized fragments. Cross-dataset 3D generalization claims require additional mapping and overlap checks.', '- New splits do not reproduce the splits used to train the supplied saved checkpoints. Evaluation of those checkpoints on these new test rows may include examples those models already saw.', '- Missing protein atoms, protonation states, stereochemistry relative to experiment, metal coordination, sequence homology leakage and force-field readiness are not fully validated by this pipeline.','', '## How many datasets are needed?','', '**For the 3D viewer, one structural dataset is sufficient: the supplied PDBbind structure-plus-index package.** One valid complex is enough for a demonstration; 19,035 can be opened here. You do not need three additional datasets to show a pocket.', '', '**For an affinity model, use a suitable labelled training collection and separate training, validation and test subsets.** These are three splits of a dataset, not a requirement to download three different datasets. The needed sample count depends on the model and the scientific goal; these counts do not guarantee accuracy.', '', '**For all four datasets to support true 3D inputs, Davis, KIBA and Metz also need verified matched protein-ligand complex structures or a documented structure-prediction and docking workflow.** A predicted protein plus an independently generated compound shape does not establish the correct bound pose.', '', '**For physical motion, an additional kind of data is required: a simulation trajectory.** Starting structures, protonation/force-field preparation, ligand parameters, solvent/ions, equilibration and simulation are required. Starting from a bound structure does not guarantee that ordinary simulation will capture the binding event itself.','', '## Tools','', '| Tool | Purpose | Status |','|---|---|---|', '| Python 3.12 | Read archives, parse labels, create splits and serve viewer | Used |', '| RDKit | Validate ligand/SMILES chemistry, ligand bonds, formal and estimated partial charges | Used |', '| NumPy + SciPy | Store atom arrays, build pockets and distance connections | Used |', '| 3Dmol.js | Local interactive protein/compound rendering and illustrative animation | Used; downloaded library kept locally |', '| Playwright + installed Chrome | Browser tests, screenshots and animation checks | Used for verification |', '| PLIP | Classify protein-ligand interactions such as hydrogen bonds with geometric/chemical rules | Optional; not run |', '| GROMACS or another MD engine | Generate physical simulation trajectories after proper system preparation | Not run |', '', 'Documentation: [RDKit](https://www.rdkit.org/docs/RDKit_Book.html), [3Dmol.js](https://www.3dmol.org/doc/GLModel.html), [PLIP](https://plip-tool.biotec.tu-dresden.de/plip-web/plip/index), [GROMACS](https://manual.gromacs.org/current/user-guide/system-preparation.html), [PDBbind downloads](https://www.pdbbind-plus.org.cn/download).','', '## Open the viewer','', 'From PowerShell:', '', '```powershell', 'cd H:\\gfihm', '.\\start_viewer.ps1', '```', '', 'Open **http://127.0.0.1:8765/**. Stop the server with Ctrl+C. If PowerShell blocks scripts, run `.\\.venv\\Scripts\\python.exe scripts\\serve_viewer.py --port 8765` directly. The viewer reads local processed files and the source archive. It needs no internet after dependencies and the bundled library are installed.', '', 'Type a PDB ID such as `10gs`, rotate/zoom, show the full protein or pocket surface, inspect nearby residues, and play the approach illustration. Contact lines disappear during movement because their distances describe the original bound pose.', '', 'The animation is an artificial straight-line translation with a fixed protein. It is neither molecular dynamics nor a predicted binding pathway.','', '## Files and model integration','', '- `processed/pdbbind/manifest.csv`: all 19,037 results, labels, warnings, exclusion reasons and split membership.', '- `processed/pdbbind/excluded.csv`: view-only and failed complexes, with reasons.', '- `processed/pdbbind/complexes/<pdb_id>/`: `graph.npz`, `metadata.json`, `pocket.pdb`, `ligand.sdf`.', '- `processed/<davis|kiba|metz>/`: cleaned `train.csv`, `val.csv`, `test.csv`, `summary.json`, and `excluded_rows.csv`.', '- `reports/schema.json`: array names, feature meanings, masks, cutoffs and label conventions.', '- `reports/ERRORS_SIMPLE.md`: errors in school-level language.', '- `reports/data_validation.json`: independent checks on every emitted graph and the splits.', '- `reports/viewer_validation.json`, `viewer_desktop.png`, `viewer_mobile.png`: browser verification.', '- `reports/input_provenance.json`: source file sizes and SHA256 checksums.', '- `scripts/preprocess.py`: reproducible preprocessing; run with `.\\.venv\\Scripts\\python.exe scripts\\preprocess.py --workers 6`.', '', 'These are documented generic NumPy 3D graph files. Recovered 2D model inference is implemented separately in scripts/cpi_inference.py; it consumes ligand features and protein sequences. See the root README for current application status.', '', 'Original input files were preserved. The CPI app separately loads the supplied trusted model checkpoints.']
    doc+=['', '## Compound features for the three CSV datasets', '', 'Also saved 2,676 distinct ligand chemical graphs shared across the cleaned CSV datasets: Davis has 68 compounds, KIBA 2,061, and Metz 1,423 (some compounds appear in multiple datasets). These include atom types, formal charges, estimated partial charges, aromaticity, hybridization and chemical bonds. All partial-charge calculations succeeded for these compounds.', '', 'Join each split CSV to `processed/<dataset>/ligand_lookup.csv` using canonical `smiles`. Graph files are in `processed/ligands2d/`, with their schema in `reports/ligand2d_summary.json`. These graphs intentionally contain no XYZ coordinates, protein pockets or implied binding poses. Rebuild them with `.\\.venv\\Scripts\\python.exe scripts\\prepare_2d_ligands.py`.', '', 'To regenerate the written reports and assay-specific split files after preprocessing, run `.\\.venv\\Scripts\\python.exe scripts\\finalize_reports.py`. To verify outputs, run `scripts\\verify_data.py` using the same interpreter; start the viewer before running `scripts\\verify_viewer.py`.']
    doc+=['', '## Verification results']
    for filename in ('data_validation.json','additional_validation.json','viewer_validation.json'):
        path=ROOT/'reports'/filename
        if path.exists():
            validation=json.loads(path.read_text())
            doc+=['', f"- `{filename}`: {validation['result']}."]
    doc+=['', 'The data validation checks every emitted 3D graph, recomputes every saved edge distance, verifies labels and split membership, and checks that missing charges are masked. The additional check validates all 2D compound graphs and assay-specific split files. Browser checks exercise rendering, surfaces, full-protein loading, animation, invalid-ID messages and the mobile layout. These are software/data consistency tests, not evidence of model accuracy or a physical binding pathway.']
    (ROOT/'reports/PREPROCESSING_REPORT.md').write_text('\n'.join(doc)+'\n',encoding='utf-8')
    print(json.dumps(dict(failed_ligands=failures,report='reports/PREPROCESSING_REPORT.md',provenance_files=len(provenance)),indent=2))

if __name__=='__main__':main()
